    """The total for ``units`` units at the unit ``price``, after the quantity discount, rounded once at the end."""
    if units >= 1000:
        discount = 0.15
    elif units >= 500:
        discount = 0.10
    elif units >= 100:
        discount = 0.05
    else:
        discount = 0.0
    return round_price(price * units * (1 - discount))

